def main():
    root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'recomp', 'data', 'lang')    # speed.rc puts them in the exe
    if len(sys.argv) > 1:
        root = sys.argv[1]
    os.makedirs(root, exist_ok=True)
    seen = set()
    for r in ROWS:
        assert len(r) == 1 + len(LANGS), r[0]
        assert r[0] not in seen, r[0]
        seen.add(r[0])
    head = '; The port\'s strings in {name}: tools/recomp/make_lang.py writes this file (the format is in recomp/runtime/pclang.h).\n'
    with open(os.path.join(root, 'ENGLISH.txt'), 'w', encoding='utf-8', newline='\n') as f:
        f.write(head.format(name='English'))
        f.write('; The port says its own strings in English in the code; a line here (English<TAB>other English) changes one.\n')
        f.write('@name English\n')
    for i, lang in enumerate(LANGS):
        with open(os.path.join(root, lang + '.txt'), 'w', encoding='utf-8', newline='\n') as f:
            f.write(head.format(name=NAMES[lang]))
            f.write('@name ' + NAMES[lang] + '\n')
            for r in ROWS:
                f.write(r[0] + '\t' + r[1 + i].replace("\\'", "'") + '\n')     # an r'' row keeps its \' as it is
    # The Russian disc's (pclang.cpp): its English slot is Russian, and these are the port's strings for it. The letters its font
    # has: the Cyrillic ones and ASCII (\xNN is a byte as it is, a button's icon).
    assert set(lang_ru.RU) == seen, sorted(set(lang_ru.RU) ^ seen)
    with open(os.path.join(root, 'RUSSIAN_DISC.txt'), 'w', encoding='utf-8', newline='\n') as f:
        f.write(head.format(name='Russian, for the Russian disc (its English slot is Russian)'))
        f.write('@name Русский\n')
        rows = [(r[0], lang_ru.RU[r[0]]) for r in ROWS] + [(k, v) for k, v in lang_ru.EXTRA.items() if k not in seen]
        for k, v in rows:
            assert all(ch == '@' or ' ' <= ch <= '~' or 'А' <= ch <= 'я' for ch in v), (k, v)
            f.write(k + '\t' + v + '\n')
    print('wrote', len(LANGS) + 1, 'files,', len(ROWS), 'rows each, and RUSSIAN_DISC.txt, to', os.path.normpath(root))


if __name__ == '__main__':
    main()
